{
  "implementation": "def solve(case):
    capacity = case["capacity"]
    trials = case["trials"]
    memory = []
    failure_index = {}
    for i, trial in enumerate(trials):
        entry = {
            "last_trial": i,
            "reflection": trial["reflection"],
            "signature": trial["signature"],
            "success": trial["success"]
        }
        if not trial["success"]:
            sig = trial["signature"]
            if sig in failure_index:
                idx = failure_index[sig]
                memory[idx] = entry
            else:
                memory.append(entry)
                failure_index[sig] = len(memory) - 1
        else:
            memory.append(entry)

    def sort_key(e):
        return (0 if not e["success"] else 1, -e["last_trial"], e["signature"])

    memory.sort(key=sort_key)
    memory = memory[:capacity]
    memory.sort(key=lambda e: e["last_trial"])
    signatures = [e["signature"] for e in memory]
    return {"memory": memory, "signatures": signatures}"
}
